export type TraceRow = { step: string; values: string; reason: string }
export type LessonContent = {
  intro: string
  explanation: string[]
  everyday: string
  code: string[]
  lineNotes: string[]
  trace: TraceRow[]
  output: string[]
  errors: string[]
  when: string
}

const entry = (intro: string, explanation: string[], everyday: string, code: string[], lineNotes: string[], trace: TraceRow[], output: string[], errors: string[], when: string): LessonContent => ({ intro, explanation, everyday, code, lineNotes, trace, output, errors, when })

export const lessonContent: Record<string, LessonContent> = {
  "Qué es un programa y un algoritmo": entry("Distinguirás la idea de algoritmo de su implementación como programa Java y aprenderás a transformar una tarea cotidiana en pasos comprobables.", ["Un algoritmo es una secuencia finita y ordenada de instrucciones que resuelve un problema. No depende de un lenguaje: una receta, una lista de pasos o un diagrama pueden describirlo.", "Un programa expresa ese algoritmo con la sintaxis de un lenguaje para que el ordenador pueda ejecutarlo. Antes de escribir código conviene precisar los datos de entrada, las operaciones y el resultado esperado.", "En este ejemplo el algoritmo suma dos cantidades conocidas. La clase y main son la estructura mínima que permite a Java empezar a ejecutar instrucciones."], "Calcular el total de una compra: anotar los precios, sumarlos y mostrar el importe es el algoritmo; escribir esos pasos en Java produce el programa.", ["public class Suma {", "    public static void main(String[] args) {", "        int cuadernos = 3;", "        int precio = 2;", "        int total = cuadernos * precio;", "        System.out.println(total);", "    }", "}"], ["Declara una clase pública. El nombre del archivo debe ser Suma.java.", "Punto de entrada: la JVM comienza aquí y ejecuta su bloque.", "Dato de entrada: cantidad de cuadernos, un entero.", "Segundo dato de entrada: precio unitario en euros enteros.", "Paso del algoritmo: multiplica cantidad por precio y guarda el resultado.", "Presenta el resultado calculado en la consola.", "Cierra el método main.", "Cierra la clase."], [{ step: "Leer cantidades", values: "cuadernos=3, precio=2", reason: "Se fijan los datos iniciales del problema." }, { step: "Calcular", values: "total=3 × 2 = 6", reason: "La multiplicación aplica la regla del algoritmo." }, { step: "Mostrar", values: "total=6", reason: "println escribe el valor obtenido." }], ["6"], ["Empezar a programar sin definir qué resultado se busca: escribe antes una entrada y una salida de ejemplo.", "Confundir algoritmo con Java: el algoritmo es la solución lógica; Java es una forma de expresarla.", "Omitir un paso: comprueba manualmente que las operaciones transforman la entrada en la salida."], "Úsalo siempre que un problema parezca grande: divide el trabajo en entrada, proceso y salida antes de codificar."),
  "Sistemas de numeración": entry("Aprenderás a interpretar números en base 2, 8, 10 y 16 y a convertirlos sin confundir el valor con la forma de escribirlo.", ["La base indica cuántos símbolos distintos puede usar cada posición. En decimal usamos diez símbolos; en binario, dos. El valor de cada dígito depende de su posición y de potencias de la base.", "Por ejemplo, 1011₂ equivale a 1×8 + 0×4 + 1×2 + 1×1 = 11₁₀. Hexadecimal usa 0–9 y A–F para representar valores de diez a quince; cada dígito hexadecimal equivale a cuatro bits.", "Java permite convertir enteros positivos con Integer.toBinaryString, toOctalString y toHexString. Estas funciones devuelven texto: el valor numérico no cambia, solo su representación."], "Un panel con interruptores apagado/encendido representa bits: cada interruptor aporta una potencia de dos, igual que las posiciones de un número binario.", ["public class Bases {", "    public static void main(String[] args) {", "        int decimal = 11;", "        System.out.println(Integer.toBinaryString(decimal));", "        System.out.println(Integer.toOctalString(decimal));", "        System.out.println(Integer.toHexString(decimal));", "    }", "}"], ["Clase del programa; guarda este código como Bases.java.", "Inicio de ejecución de la aplicación.", "El número once se almacena en decimal; int no guarda una base especial.", "Convierte el valor a su representación binaria y la imprime como texto.", "Convierte el mismo valor a octal.", "Convierte el mismo valor a hexadecimal; la salida puede usar letras minúsculas.", "Fin de main.", "Fin de la clase."], [{ step: "Valor inicial", values: "decimal=11", reason: "Las tres conversiones reciben el mismo entero." }, { step: "Base 2", values: "11₁₀ = 1011₂", reason: "8 + 2 + 1 suma once." }, { step: "Bases 8 y 16", values: "13₈, b₁₆", reason: "Las representaciones son distintas, el valor sigue siendo once." }], ["1011", "13", "b"], ["Leer 101 como ciento uno: sin subíndice se suele asumir decimal; anota la base cuando haya ambigüedad.", "Creer que 10₂ vale diez: en binario representa dos.", "Usar estas funciones con negativos esperando una representación matemática sin signo: Java muestra la representación binaria de complemento a dos del int."], "Usa conversiones de base para estudiar codificación, máscaras de bits o formatos compactos; para cálculos habituales deja los datos como int."),
  "Código ASCII": entry("Relacionarás caracteres con códigos numéricos, distinguirás ASCII de Unicode y consultarás el valor de un carácter en Java.", ["ASCII asigna valores numéricos a un conjunto histórico de 128 caracteres: letras inglesas, dígitos, signos y controles. La letra A mayúscula es 65 y a minúscula es 97.", "Java usa Unicode para char, por lo que puede representar mucho más que ASCII. Un char ocupa una unidad UTF-16; no todos los caracteres Unicode caben en una sola unidad, así que no confundas char con cualquier símbolo visual.", "Al convertir char a int obtenemos su unidad UTF-16. Para los caracteres ASCII básicos ese número coincide con el código ASCII conocido."], "Un teclado envía códigos que el sistema interpreta como letras; ASCII fue una tabla común para acordar qué número significa cada carácter básico.", ["public class CodigoCaracter {", "    public static void main(String[] args) {", "        char letra = 'A';", "        int codigo = letra;", "        System.out.println(letra + \" = \" + codigo);", "    }", "}"], ["Declara la clase contenedora.", "La JVM ejecuta el método main.", "Guarda el carácter A; char usa comillas simples.", "La conversión char a int es automática y conserva el código numérico.", "Concatena texto y valores y muestra A = 65.", "Cierra main.", "Cierra la clase."], [{ step: "Carácter", values: "letra='A'", reason: "El literal char representa una sola unidad de texto." }, { step: "Conversión", values: "codigo=65", reason: "La promoción a int obtiene el valor numérico Unicode de A." }, { step: "Salida", values: "A = 65", reason: "La concatenación convierte el entero a texto para imprimirlo." }], ["A = 65"], ["Escribir " + "A" + " con comillas dobles al asignar a char: char necesita comillas simples.", "Afirmar que todos los caracteres Unicode caben en char: algunos símbolos se representan mediante dos unidades.", "Esperar que acentos y emoji pertenezcan al ASCII básico: ASCII solo cubre 0–127."], "Úsalo para comprender codificación y conversiones; para texto real usa String y métodos de caracteres Unicode."),
  "JDK, JVM y JRE": entry("Comprenderás cómo se compila y ejecuta Java, y qué papel cumplen el JDK, la JVM y el entorno de ejecución.", ["El JDK incluye herramientas para desarrollar, entre ellas el compilador javac. El compilador transforma archivos .java en bytecode .class.", "La JVM interpreta o compila ese bytecode para el sistema operativo y procesador disponibles. Esa máquina virtual es la pieza que permite ejecutar el mismo bytecode en distintos sistemas que tengan una JVM compatible.", "JRE suele nombrar el entorno de ejecución (JVM y bibliotecas necesarias). En distribuciones actuales el empaquetado puede variar; para programar instala un JDK. Flujo: fuente Java → javac → bytecode → JVM → ejecución."], "Una partitura no es la interpretación musical: el archivo .java es la fuente, el bytecode es una forma intermedia y la JVM es el intérprete/adaptador de ejecución.", ["public class FlujoJava {", "    public static void main(String[] args) {", "        System.out.println(\"Hola, JVM\");", "    }", "}"], ["La clase pública define el nombre del archivo fuente: FlujoJava.java.", "La JVM busca este método como punto de entrada del programa.", "La instrucción se compila a bytecode y la JVM ejecuta la impresión.", "Fin del método principal.", "Fin de la clase compilada."], [{ step: "Fuente", values: "FlujoJava.java", reason: "El programador escribe código fuente legible." }, { step: "Compilar", values: "javac → FlujoJava.class", reason: "El JDK contiene el compilador que produce bytecode." }, { step: "Ejecutar", values: "java FlujoJava → Hola, JVM", reason: "La JVM carga la clase y ejecuta main." }], ["Hola, JVM"], ["Usar javac sin tener un JDK instalado: instala un JDK y revisa la configuración del IDE.", "Creer que la JVM es el compilador fuente: javac compila .java; la JVM ejecuta bytecode.", "Pensar que Java se ejecuta sin adaptación en cualquier dispositivo: hace falta una JVM adecuada."], "Identifica esta cadena cuando un error de compilación sea distinto de un error que aparece al ejecutar el programa."),
  "Estructura de un programa Java": entry("Reconocerás las partes de una clase Java ejecutable: clase, método main, instrucciones, bloques y terminadores.", ["Una clase agrupa código relacionado. Si es pública, su nombre debe coincidir exactamente con el archivo .java, respetando mayúsculas y minúsculas.", "La firma public static void main(String[] args) es el punto de entrada habitual de una aplicación de consola. Las llaves delimitan bloques y cada instrucción sencilla termina con punto y coma.", "En versiones recientes existen otras formas de lanzar programas sencillos, pero aprender la estructura explícita facilita comprender clases y métodos del curso."], "La clase es como una carpeta del programa, main es la puerta por la que empieza la ejecución y cada instrucción es una tarea en orden.", ["public class Hola {", "    public static void main(String[] args) {", "        String mensaje = \"Hola, DAM\";", "        System.out.println(mensaje);", "    }", "}"], ["Declara la clase pública Hola; el archivo debe llamarse Hola.java.", "Define el método principal, que la JVM invoca al arrancar.", "Declara e inicializa una variable String dentro de main.", "Muestra en consola el contenido de mensaje.", "Cierra el bloque de main.", "Cierra el bloque de la clase."], [{ step: "Cargar clase", values: "Hola", reason: "La JVM encuentra la clase indicada para iniciar." }, { step: "Entrar a main", values: "mensaje aún no existe", reason: "El cuerpo se ejecuta desde arriba." }, { step: "Asignar y mostrar", values: "mensaje=Hola, DAM", reason: "La declaración crea la variable; println la consulta." }], ["Hola, DAM"], ["Desajustar nombre de archivo y clase pública: compáralos letra por letra.", "Omitir ; al final de una declaración: añade el terminador antes de compilar.", "Poner una instrucción fuera de cualquier método: coloca el código ejecutable dentro de main."], "Es la base de cualquier ejemplo de consola; en proyectos mayores el programa se reparte en varias clases."),
  "Tipos de datos primitivos": entry("Elegirás entre byte, short, int, long, float, double, char y boolean según el rango y la precisión que necesite cada dato.", ["Los enteros byte, short, int y long ocupan rangos cada vez mayores; para enteros comunes se suele usar int. Los literales long suelen llevar L al final.", "float y double representan aproximaciones de números reales; double es la opción habitual. Un literal float necesita sufijo f. Para cantidades monetarias exactas se prefiere BigDecimal, aunque aquí se estudian los primitivos.", "char almacena una unidad UTF-16 y usa comillas simples. boolean solo puede ser true o false. Los primitivos no son objetos y cada uno tiene reglas de conversión propias."], "Una caja etiquetada como 'número entero', 'decimal', 'letra' o 'sí/no' ayuda a escoger el tipo apropiado antes de guardar cada dato.", ["public class Tipos {", "    public static void main(String[] args) {", "        byte edad = 18;", "        long habitantes = 8_000_000_000L;", "        float nota = 8.5f;", "        double precio = 12.75;", "        char inicial = 'M';", "        boolean aprobado = true;", "        System.out.println(edad + \" \" + habitantes + \" \" + nota + \" \" + precio + \" \" + inicial + \" \" + aprobado);", "    }", "}"], ["Abre la clase pública Tipos.", "Inicia el método de la aplicación.", "byte guarda un entero pequeño; 18 cabe dentro de su rango.", "long admite enteros grandes; L marca el literal long y los guiones bajos facilitan leerlo.", "float guarda una aproximación decimal; f evita que el literal se interprete como double.", "double almacena una aproximación decimal con más precisión que float.", "char contiene un carácter entre comillas simples.", "boolean representa una condición verdadera o falsa.", "Concatena cada valor con espacios y los muestra en una sola línea.", "Cierra main.", "Cierra la clase."], [{ step: "Enteros", values: "edad=18; habitantes=8000000000", reason: "Cada entero debe caber en el rango de su tipo." }, { step: "Decimales", values: "nota≈8.5; precio≈12.75", reason: "float y double son representaciones binarias aproximadas." }, { step: "Carácter y condición", values: "inicial='M'; aprobado=true", reason: "char y boolean representan categorías distintas." }], ["18 8000000000 8.5 12.75 M true"], ["Asignar 8.5 a float sin f: escribe 8.5f o utiliza double.", "Olvidar L en un literal demasiado grande: el compilador puede rechazarlo como int.", "Usar == para comparar texto: String no es primitivo; se suele comparar con equals."], "Elige el tipo más sencillo que represente correctamente el dato. No uses float para dinero real ni char para frases."),
  "Variables y declaración": entry("Crearás variables, les darás nombres válidos y seguirás cómo cambia el valor almacenado durante una ejecución.", ["Una variable es un espacio nombrado cuyo valor puede consultarse y, si no es final, cambiar. Declararla establece el tipo y el nombre; inicializarla asigna su primer valor.", "Java exige que una variable local tenga un valor asignado antes de leerla. Los nombres suelen usar lowerCamelCase y describir qué contiene, por ejemplo totalCompra.", "El tipo se comprueba al compilar: una variable int no puede recibir directamente una frase. El valor actual puede cambiar sin cambiar el tipo."], "Una casilla de una hoja de cálculo con una etiqueta contiene un valor que puedes actualizar y volver a usar en una fórmula.", ["public class Variables {", "    public static void main(String[] args) {", "        int puntos = 10;", "        System.out.println(puntos);", "        puntos = puntos + 5;", "        System.out.println(puntos);", "    }", "}"], ["Define la clase que contiene el ejemplo.", "La ejecución empieza en main.", "Declara puntos como int y le asigna 10.", "Lee el valor actual y lo muestra.", "Evalúa primero puntos + 5 y luego guarda 15 en la misma variable.", "Muestra el nuevo valor; la asignación anterior ya fue sustituida.", "Cierra main.", "Cierra la clase."], [{ step: "Declaración", values: "puntos=10", reason: "La variable nace con un valor inicial válido." }, { step: "Primera salida", values: "puntos=10", reason: "println consulta el estado actual." }, { step: "Reasignación", values: "10+5 → puntos=15", reason: "El lado derecho se calcula antes de guardar." }, { step: "Segunda salida", values: "puntos=15", reason: "Se imprime el valor actualizado." }], ["10", "15"], ["Leer una variable local antes de inicializarla: asigna un valor en todos los caminos posibles.", "Usar un nombre que no describe el dato: nombres precisos reducen errores de razonamiento.", "Escribir int puntos == 10: la declaración usa = para asignar, no == para comparar."], "Usa variables para valores que cambian o se reutilizan; crea una variable descriptiva en lugar de repetir una expresión compleja."),
  "Constantes y final": entry("Diferenciarás variables que pueden cambiar de valores constantes y usarás final para impedir una segunda asignación.", ["La palabra clave final hace que una variable solo pueda asignarse una vez. Una constante debe inicializarse antes de leerse y no se puede reasignar.", "Por convención, las constantes static final compartidas se escriben en MAYÚSCULAS_CON_GUIONES. No conviertas en constante un valor que legítimamente cambia durante el programa.", "final protege la referencia de reasignaciones, pero no vuelve inmutable automáticamente el contenido de un objeto mutable."], "Una tarifa publicada en un cartel permanece fija durante el cálculo; la cantidad de artículos de una compra sí puede cambiar.", ["public class Constante {", "    public static void main(String[] args) {", "        final double IVA = 0.21;", "        double precio = 100.0;", "        double total = precio * (1 + IVA);", "        System.out.println(total);", "    }", "}"], ["Declara la clase del ejemplo.", "Punto de entrada ejecutable.", "Declara una constante decimal y la inicializa en el mismo momento.", "El precio es variable porque puede cambiar según la compra.", "Calcula el precio con IVA sin modificar la tasa guardada.", "Muestra el total calculado.", "Cierra main.", "Cierra la clase."], [{ step: "Constante", values: "IVA=0.21 (no cambia)", reason: "final permite asignarla una sola vez." }, { step: "Entrada", values: "precio=100.0", reason: "El precio representa un dato de la compra." }, { step: "Cálculo", values: "100 × (1 + 0.21) = 121", reason: "Se usa la constante en la fórmula." }], ["121.0"], ["Intentar cambiar IVA después de inicializarla: decide el valor antes de usar la constante.", "Declarar final sin asignación y olvidarla: Java exige inicializarla exactamente una vez.", "Usar int para una tasa decimal: elige double para este ejemplo académico."], "Usa final para valores que deben mantenerse constantes, como límites, tasas o configuraciones de solo lectura."),
  "Operadores aritméticos": entry("Aplicarás suma, resta, multiplicación, división y resto, teniendo en cuenta los tipos enteros y decimales.", ["+, -, * y / realizan las cuatro operaciones habituales. Cuando ambos operandos son enteros, la división también es entera: 7 / 2 produce 3 y descarta el resto.", "% devuelve el resto de una división entera y ayuda, por ejemplo, a detectar pares con n % 2 == 0. Dividir entre cero con enteros causa ArithmeticException.", "Para conservar decimales, al menos un operando debe ser double o float. Los paréntesis permiten expresar claramente qué operación debe ocurrir primero."], "Al repartir siete galletas entre dos personas, cada una recibe tres y sobra una: la división entera da 3 y el operador resto da 1.", ["public class Aritmetica {", "    public static void main(String[] args) {", "        int total = 7;", "        int personas = 2;", "        int porPersona = total / personas;", "        int sobrantes = total % personas;", "        double exacto = (double) total / personas;", "        System.out.println(porPersona + \" y sobra \" + sobrantes);", "        System.out.println(exacto);", "    }", "}"], ["Declara la clase del programa.", "Abre el punto de entrada.", "Guarda el total de objetos.", "Guarda cuántos grupos los reparten.", "La división entre int produce 3, no 3.5.", "El resto de dividir 7 entre 2 es 1.", "Convierte total a double antes de dividir; el resultado conserva la fracción.", "Muestra cociente entero y sobrante.", "Muestra la división decimal.", "Cierra main.", "Cierra la clase."], [{ step: "Operandos", values: "total=7, personas=2", reason: "Ambos son enteros." }, { step: "División entera", values: "porPersona=3", reason: "La parte decimal se descarta al dividir int entre int." }, { step: "Resto", values: "sobrantes=1", reason: "7 = 2×3 + 1." }, { step: "Casting", values: "exacto=3.5", reason: "La conversión ocurre antes de la división." }], ["3 y sobra 1", "3.5"], ["Esperar que 7 / 2 dé 3.5 siendo ambos int: convierte antes de dividir.", "Olvidar paréntesis en una expresión compleja: usa paréntesis para que la intención sea visible.", "Dividir por una variable que vale cero: valida el divisor antes de la operación."], "Utiliza % para restos y patrones periódicos; si necesitas fracciones, verifica que el tipo de la operación sea decimal."),
  "Operadores relacionales y lógicos": entry("Construirás condiciones con comparaciones y combinarás sus resultados booleanos mediante &&, || y !.", ["Los operadores <, <=, >, >=, == y != comparan valores y producen true o false. No son intercambiables: = asigna; == compara valores primitivos.", "&& requiere que ambas condiciones sean verdaderas; || requiere al menos una; ! invierte un booleano. Java aplica cortocircuito: si el primer operando de && es falso, no evalúa el segundo.", "Los paréntesis hacen explícita la agrupación, sobre todo al mezclar && y ||. Una condición clara expresa la regla del dominio, no solo una fórmula compacta."], "Para entrar a una actividad quizá necesitas tener al menos 16 años y llevar autorización; para una actividad alternativa basta una de esas condiciones.", ["public class AccesoLogico {", "    public static void main(String[] args) {", "        int edad = 17;", "        boolean permiso = true;", "        boolean puedeEntrar = edad >= 16 && permiso;", "        System.out.println(puedeEntrar);", "    }", "}"], ["Declara la clase del ejemplo.", "Inicia la aplicación.", "Guarda la edad que se va a evaluar.", "Guarda si se dispone de permiso.", "Compara edad y combina ambos resultados con &&.", "Imprime true solo si las dos condiciones son verdaderas.", "Cierra main.", "Cierra la clase."], [{ step: "Primera comparación", values: "edad >= 16 → true", reason: "17 es mayor o igual que 16." }, { step: "Segunda condición", values: "permiso → true", reason: "El permiso también está concedido." }, { step: "AND lógico", values: "true && true → true", reason: "&& exige que ambas partes sean verdaderas." }], ["true"], ["Confundir = con == en una condición: == compara, = asigna.", "Usar & en vez de && sin motivo: && expresa cortocircuito lógico.", "Olvidar agrupar una regla mixta: añade paréntesis para mostrar qué alternativa se combina."], "Combina varias reglas de validación. Si la condición crece demasiado, guárdala en booleanos con nombres significativos."),
  "Incrementos y decrementos": entry("Entenderás ++ y -- y la diferencia práctica entre las formas prefija y postfija dentro de expresiones.", ["i++ incrementa i en uno y ++i también; fuera de una expresión mayor ambas dejan el mismo valor final. Lo mismo ocurre con --.", "La diferencia es el valor que produce la expresión: i++ produce el valor anterior y luego incrementa; ++i incrementa primero y produce el nuevo valor.", "En una línea aislada, usa la forma que prefieras según el estilo del curso. Evita mezclar varios incrementos en una sola expresión porque hace difícil seguir el estado."], "Un contador de pasos aumenta una unidad por cada persona que termina una actividad.", ["public class Incremento {", "    public static void main(String[] args) {", "        int intentos = 0;", "        intentos++;", "        int anterior = intentos++;", "        int actual = ++intentos;", "        System.out.println(anterior + \" / \" + actual + \" / \" + intentos);", "    }", "}"], ["Define la clase del ejemplo.", "Abre el método principal.", "Inicializa el contador a cero.", "Incrementa intentos: ahora vale uno.", "Guarda el valor previo, 1, y después intentos pasa a 2.", "Incrementa primero a 3 y guarda ese valor en actual.", "Muestra los dos valores guardados y el contador final.", "Cierra main.", "Cierra la clase."], [{ step: "Inicio", values: "intentos=0", reason: "El contador empieza en cero." }, { step: "Postincremento aislado", values: "intentos=1", reason: "La variable se incrementa en una unidad." }, { step: "Postincremento en asignación", values: "anterior=1; intentos=2", reason: "La expresión entrega primero el valor antiguo." }, { step: "Preincremento", values: "actual=3; intentos=3", reason: "La variable cambia antes de entregar el valor." }], ["1 / 3 / 3"], ["Creer que intentos++ no incrementa hasta otra línea: el incremento ocurre como parte de esa expresión.", "Usar ++ en boolean o double esperando un efecto intuitivo: aplica a variables numéricas adecuadas.", "Combinar varios ++ en una expresión: separa los pasos para poder verificar el orden."], "Usa incremento para contadores de bucles; en expresiones complejas, prefiere una asignación explícita en una línea independiente."),
  "Prioridad de operadores": entry("Predecirás el orden de evaluación de una expresión y usarás paréntesis para documentar el cálculo.", ["La multiplicación y la división se evalúan antes que suma y resta. Operadores con igual prioridad suelen asociarse de izquierda a derecha; la asignación se evalúa al final.", "La prioridad no sustituye a la lectura cuidadosa: paréntesis agrupan subexpresiones y dejan clara la intención para quien lee.", "No memorices una tabla completa para escribir fórmulas difíciles. Descompón el cálculo en variables intermedias si eso mejora la comprensión."], "Una cuenta de compra aplica primero el precio por cantidad y después añade el coste de envío; los paréntesis fijan esa agrupación.", ["public class Prioridad {", "    public static void main(String[] args) {", "        int resultado = 2 + 3 * 4;", "        int agrupado = (2 + 3) * 4;", "        System.out.println(resultado);", "        System.out.println(agrupado);", "    }", "}"], ["Declara la clase del ejemplo.", "Punto de entrada.", "Multiplica 3 por 4 antes de sumar 2.", "Los paréntesis obligan a sumar 2 y 3 primero.", "Muestra el primer cálculo.", "Muestra el cálculo con agrupación distinta.", "Cierra main.", "Cierra la clase."], [{ step: "Sin paréntesis", values: "3×4=12; 2+12=14", reason: "La multiplicación tiene prioridad sobre la suma." }, { step: "Con paréntesis", values: "2+3=5; 5×4=20", reason: "El grupo entre paréntesis se calcula primero." }], ["14", "20"], ["Evaluar siempre de izquierda a derecha sin atender a la prioridad: revisa la precedencia o añade paréntesis.", "Escribir una expresión extensa y opaca: divide en variables intermedias.", "Añadir paréntesis que cambian el resultado sin comprobarlos: calcula un ejemplo a mano."], "Usa paréntesis aunque no sean estrictamente necesarios cuando hacen explícita una regla de negocio."),
  "Conversiones y casting": entry("Distinguirás conversiones automáticas de conversiones explícitas y detectarás cuándo una conversión puede perder información.", ["Java amplía algunos tipos automáticamente cuando el destino puede representar el valor de origen, por ejemplo int a double. Esta conversión se denomina widening.", "Al estrechar de double a int se requiere casting: (int) valor. Se descarta la parte decimal hacia cero; no se redondea. Un casting no garantiza que el valor quepa sin desbordamiento.", "Para redondear decimales, utiliza Math.round; para datos de entrada, valida el rango antes de convertir."], "Convertir una medida decimal a una cantidad entera de cajas completas obliga a decidir qué hacer con la fracción: el casting la descarta, no la redondea.", ["public class Conversion {", "    public static void main(String[] args) {", "        int unidades = 7;", "        double exacto = unidades;", "        double peso = 8.75;", "        int truncado = (int) peso;", "        long redondeado = Math.round(peso);", "        System.out.println(exacto + \" / \" + truncado + \" / \" + redondeado);", "    }", "}"], ["Declara la clase de conversión.", "Abre el método principal.", "Guarda un entero.", "Java amplía int a double automáticamente: 7.0.", "Guarda una cantidad decimal aproximada.", "El casting conserva solo la parte entera: 8.", "Math.round redondea al entero más cercano y devuelve long.", "Muestra los tres resultados separados por barras.", "Cierra main.", "Cierra la clase."], [{ step: "Widening", values: "unidades=7 → exacto=7.0", reason: "El tipo de destino puede representar el valor entero." }, { step: "Casting estrecho", values: "peso=8.75 → truncado=8", reason: "Se elimina la parte fraccionaria, no se redondea." }, { step: "Redondeo", values: "Math.round(8.75)=9", reason: "El método aplica la regla de redondeo." }], ["7.0 / 8 / 9"], ["Esperar que (int) 8.75 redondee: produce 8; usa Math.round si eso necesitas.", "Forzar una conversión sin revisar el rango: el estrechamiento puede perder o alterar información.", "Creer que int / int conserva decimales: convierte uno de los operandos antes de dividir."], "Convierte explícitamente cuando la pérdida de precisión sea una decisión deliberada y visible."),
  "Entrada con Scanner": entry("Leerás texto y números desde la consola con Scanner, y aprenderás a alternar nextInt con nextLine sin perder entradas.", ["Scanner conecta System.in con métodos que interpretan lo que escribe el usuario. nextInt lee el siguiente token como entero; nextLine consume el resto de la línea actual.", "Después de nextInt queda el salto de línea pendiente. Si llamas enseguida a nextLine, puede recibir esa línea vacía; consume primero el salto con una llamada adicional a nextLine.", "Cierra el Scanner cuando ya no lo necesitas. En aplicaciones sencillas no cierres System.in antes de acabar otras lecturas."], "Es como un formulario en consola: primero se lee la edad numérica y luego una frase completa con el nombre.", ["import java.util.Scanner;", "public class Entrada {", "    public static void main(String[] args) {", "        Scanner teclado = new Scanner(System.in);", "        System.out.print(\"Edad: \" );", "        int edad = teclado.nextInt();", "        teclado.nextLine();", "        System.out.print(\"Nombre: \" );", "        String nombre = teclado.nextLine();", "        System.out.println(nombre + \" tiene \" + edad);", "        teclado.close();", "    }", "}"], ["Importa Scanner desde la biblioteca estándar.", "Declara la clase pública Entrada.", "Punto de entrada.", "Crea el lector asociado a la entrada estándar.", "Pide la edad sin saltar de línea.", "Lee un token entero; si se escribe texto, puede producir InputMismatchException.", "Consume el salto de línea que quedó tras nextInt.", "Solicita el nombre completo.", "Lee la línea completa, incluidos espacios internos.", "Muestra los datos leídos.", "Libera el Scanner cuando no se harán más lecturas.", "Cierra main.", "Cierra la clase."], [{ step: "Leer edad", values: "entrada: 19 ↦ edad=19", reason: "nextInt interpreta el siguiente token como int." }, { step: "Consumir fin de línea", values: "el salto pendiente se descarta", reason: "Así nextLine no recibe una cadena vacía accidental." }, { step: "Leer nombre", values: "entrada: Ana Ruiz ↦ nombre=Ana Ruiz", reason: "nextLine toma el resto de la línea." }], ["Edad: 19", "Nombre: Ana Ruiz", "Ana Ruiz tiene 19"], ["Olvidar el import: añade java.util.Scanner al principio del archivo.", "Mezclar nextInt y nextLine y obtener un nombre vacío: consume el salto de línea pendiente.", "Ingresar texto donde se esperaba int: valida o captura InputMismatchException."], "Usa Scanner para ejercicios y programas de consola; para interfaces gráficas o servicios hay otras fuentes de entrada."),
  "Salida por consola": entry("Usarás print, println y printf para mostrar información comprensible y formatear valores.", ["System.out es el flujo estándar de salida. print escribe sin avanzar de línea; println añade un salto; printf permite especificar un formato.", "En printf, %s representa texto, %d enteros y %.2f un decimal con dos posiciones. El especificador %n crea un salto independiente del sistema operativo.", "La concatenación con + es cómoda para mensajes pequeños; si mezclas operaciones aritméticas con texto, añade paréntesis para evitar resultados inesperados."], "Un recibo separa cada concepto en una línea y muestra el precio con dos decimales para que se lea fácilmente.", ["public class Consola {", "    public static void main(String[] args) {", "        String producto = \"Cuaderno\";", "        int unidades = 2;", "        double precio = 3.5;", "        System.out.print(\"Producto: \" );", "        System.out.println(producto);", "        System.out.printf(\"%d unidades · %.2f €%n\", unidades, precio);", "    }", "}"], ["Declara la clase del ejemplo.", "Punto de entrada de la aplicación.", "Guarda la etiqueta del producto.", "Guarda cuántas unidades hay.", "Guarda el precio como decimal.", "Escribe una etiqueta y permanece en la misma línea.", "Escribe el nombre y después pasa a la siguiente línea.", "Inserta enteros y un decimal formateado con dos posiciones; %n añade salto.", "Cierra main.", "Cierra la clase."], [{ step: "Preparar valores", values: "producto=Cuaderno; unidades=2; precio=3.5", reason: "Las variables son argumentos de salida." }, { step: "print", values: "cursor tras 'Producto: '", reason: "print no agrega salto." }, { step: "println y printf", values: "líneas con nombre y formato decimal", reason: "println salta; printf aplica los especificadores." }], ["Producto: Cuaderno", "2 unidades · 3.50 €"], ["Escribir %f cuando necesitas solo dos decimales: usa %.2f.", "Pasar argumentos en orden incorrecto a printf: comprueba que cada marcador corresponde a su valor.", "Suponer que println redondea valores almacenados: solo los presenta; no modifica las variables."], "Usa println para resultados sencillos y printf cuando necesites un formato predecible."),
  "Ámbito de variables": entry("Identificarás dónde existe una variable, qué bloque puede leerla y por qué una variable local desaparece al salir del bloque.", ["El ámbito es la región del código donde un nombre está disponible. Una variable local declarada dentro de un método solo vive en ese método.", "Una variable declarada dentro de un bloque como if o for solo es visible desde su declaración hasta la llave que cierra ese bloque. Dos bloques separados pueden tener variables con el mismo nombre.", "Declara variables cerca del primer uso y evita duplicar nombres si eso confunde el seguimiento. La duración de vida y el ámbito están relacionados, pero no significan exactamente lo mismo."], "Una tarjeta de acceso solo sirve dentro de una sala; una vez que sales de la sala, esa tarjeta local deja de estar disponible en ese contexto.", ["public class Ambito {", "    public static void main(String[] args) {", "        int puntos = 10;", "        if (puntos >= 5) {", "            int bonus = 2;", "            puntos += bonus;", "        }", "        System.out.println(puntos);", "    }", "}"], ["Declara la clase del ejemplo.", "Abre main; las variables locales de este método pertenecen a su bloque.", "puntos existe hasta el final de main.", "Abre un bloque condicional anidado.", "bonus solo existe dentro de las llaves del if.", "Lee bonus y actualiza puntos mientras ambos nombres están en ámbito.", "Cierra el bloque: bonus deja de estar disponible aquí.", "puntos sigue en ámbito y su valor actualizado se imprime.", "Cierra main.", "Cierra la clase."], [{ step: "Antes del if", values: "puntos=10", reason: "puntos se declaró en main." }, { step: "Dentro del if", values: "bonus=2; puntos=12", reason: "La condición es verdadera y bonus existe en ese bloque." }, { step: "Después del if", values: "puntos=12; bonus fuera de ámbito", reason: "Al cerrar el bloque no se puede consultar bonus." }], ["12"], ["Consultar una variable fuera de sus llaves: mueve su declaración si realmente debe sobrevivir al bloque.", "Declarar el mismo nombre dentro de un ámbito solapado: evita la redeclaración que Java no permite.", "Inicializar una variable solo en una rama y leerla en todas: garantiza asignación en cada camino."], "Mantén el ámbito lo más pequeño posible para reducir dependencias y errores."),
  "Comentarios y Javadoc": entry("Documentarás intención y contratos sin confundir comentarios con instrucciones ejecutables.", ["// añade un comentario de una línea; /* ... */ puede abarcar varias. El compilador ignora ambos formatos, por eso un comentario desactualizado no cambia ni corrige el programa.", "Javadoc comienza con /** y se coloca antes de clases o métodos públicos. Etiquetas como @param, @return y @throws describen el contrato y permiten generar documentación HTML.", "Comenta por qué una decisión no resulta obvia. No repitas literalmente lo que el código ya dice ni uses comentarios como sustituto de nombres claros."], "En una receta, los pasos son las instrucciones y una nota explica por qué se deja reposar una masa; la nota ayuda a entender, pero no es un paso ejecutable.", ["/**", " * Convierte minutos a segundos.", " * @param minutos cantidad que se convertirá", " * @return equivalencia en segundos", " */", "public class Documentacion {", "    public static void main(String[] args) {", "        int segundos = convertir(3);", "        System.out.println(segundos); // muestra el resultado", "    }", "    static int convertir(int minutos) {", "        return minutos * 60;", "    }", "}"], ["Abre un comentario Javadoc.", "Describe el propósito del método documentado.", "Explica el parámetro de entrada.", "Describe el valor que devuelve el método.", "Cierra el bloque de documentación.", "Declara la clase pública Documentacion.", "Punto de entrada del programa.", "Llama a convertir con tres minutos y guarda el retorno.", "Muestra el valor calculado; el comentario final no se ejecuta.", "Cierra main.", "Declara un método estático que recibe minutos y devuelve int.", "Devuelve minutos multiplicados por sesenta.", "Cierra el método convertir.", "Cierra la clase."], [{ step: "Llamada", values: "convertir(3)", reason: "El argumento 3 se asigna al parámetro minutos." }, { step: "Cálculo", values: "3 × 60 = 180", reason: "El método calcula y entrega un int." }, { step: "Salida", values: "segundos=180", reason: "main recibe el resultado y lo imprime." }], ["180"], ["Creer que // ejecuta una instrucción: los comentarios no alteran la ejecución.", "Documentar @param con otro nombre: debe coincidir con el parámetro real.", "Dejar comentarios que contradicen el código: actualízalos junto con el comportamiento."], "Usa Javadoc para contratos de clases y métodos que otras personas necesitan utilizar."),
  "Programación estructurada": entry("Organizarás una solución mediante secuencia, selección y repetición, las tres estructuras fundamentales de la programación estructurada.", ["La secuencia ejecuta instrucciones en orden; la selección elige una rama mediante una condición; la repetición vuelve a ejecutar un bloque mientras se cumpla una regla.", "Combinar estas estructuras permite describir muchos algoritmos sin saltos arbitrarios. Cada bloque debe tener una entrada y una salida comprensibles.", "Separar responsabilidades y evitar saltos confusos facilita leer, probar y depurar el programa."], "Para preparar una excursión lees el tiempo, decides si llevas paraguas y repites una revisión para cada persona: secuencia, selección y repetición.", ["public class Estructurada {", "    public static void main(String[] args) {", "        int nota = 7;", "        if (nota >= 5) {", "            System.out.println(\"Aprobado\");", "        }", "        for (int intento = 1; intento <= 2; intento++) {", "            System.out.println(\"Revisión \" + intento);", "        }", "    }", "}"], ["Declara la clase que agrupa el algoritmo.", "Punto de entrada.", "Dato utilizado por la selección.", "La selección evalúa si la nota alcanza el mínimo.", "Rama verdadera: comunica el resultado.", "Cierra el bloque condicional.", "La repetición ejecuta dos revisiones con un contador.", "Acción repetida para cada valor del contador.", "Cierra el bucle.", "Cierra main.", "Cierra la clase."], [{ step: "Secuencia", values: "nota=7", reason: "Las declaraciones y evaluaciones se ejecutan en orden." }, { step: "Selección", values: "7 >= 5 → true", reason: "Solo se ejecuta la rama cuyo criterio se cumple." }, { step: "Repetición", values: "intento=1 y luego 2", reason: "El cuerpo del for se ejecuta dos veces." }], ["Aprobado", "Revisión 1", "Revisión 2"], ["Resolver todo en un único bloque enorme: separa etapas y responsabilidades.", "Repetir código a mano: una estructura de repetición evita duplicación.", "Anidar condiciones innecesariamente: simplifica reglas y usa retornos tempranos cuando sean apropiados."], "Usa estas estructuras como vocabulario para planificar cualquier algoritmo antes de elegir detalles de sintaxis."),
  "Estructura secuencial": entry("Seguirás una serie de instrucciones en orden y aprenderás a rastrear cómo cada paso transforma los datos.", ["En una secuencia, Java ejecuta una instrucción y después la siguiente. Una asignación puede usar valores previos, por lo que cambiar el orden puede cambiar el resultado.", "Antes de ejecutar una secuencia, identifica qué variables se crean, qué expresiones se calculan y cuándo se muestra el resultado.", "Las instrucciones de entrada, cálculo y salida forman una estructura secuencial aunque no haya if ni bucles."], "Para preparar una bebida primero llenas el vaso, después añades agua y al final mezclas; cambiar el orden altera el resultado.", ["public class Secuencia {", "    public static void main(String[] args) {", "        int precio = 4;", "        int cantidad = 3;", "        int subtotal = precio * cantidad;", "        int descuento = 2;", "        int total = subtotal - descuento;", "        System.out.println(total);", "    }", "}"], ["Declara la clase.", "Abre main.", "Guarda el precio unitario.", "Guarda la cantidad adquirida.", "Calcula subtotal con los dos datos previos.", "Guarda el descuento aplicado.", "Calcula el importe final después del descuento.", "Muestra el total.", "Cierra main.", "Cierra la clase."], [{ step: "Paso 1", values: "precio=4", reason: "Se declara el precio." }, { step: "Paso 2", values: "cantidad=3", reason: "Se declara la cantidad." }, { step: "Paso 3", values: "subtotal=4×3=12", reason: "La operación usa las dos variables anteriores." }, { step: "Paso 4", values: "total=12−2=10", reason: "El descuento se resta al subtotal." }], ["10"], ["Calcular total antes de subtotal: Java no puede usar una variable local antes de inicializarla.", "Cambiar el orden de actualización: revisa qué estado existe en cada línea.", "Mostrar una variable intermedia por error: imprime la variable que representa la salida final."], "Usa secuencia cuando cada paso ocurre una vez y no depende de una decisión o repetición."),
  "Condicional if": entry("Ejecutarás una instrucción solo cuando una condición booleana sea verdadera.", ["if evalúa una expresión booleana. Si vale true, ejecuta su bloque; si vale false, salta el bloque y continúa después de la llave.", "Las llaves son recomendables incluso para una sola instrucción porque previenen errores al añadir líneas más tarde. La condición no debe incluir punto y coma antes del bloque.", "Una condición simple es clara cuando solo hay una acción opcional; si existen dos resultados alternativos, considera if-else."], "Una aplicación enciende una notificación si la batería está baja; si no, simplemente continúa sin mostrarla.", ["public class Aviso {", "    public static void main(String[] args) {", "        int bateria = 15;", "        if (bateria < 20) {", "            System.out.println(\"Carga el dispositivo\");", "        }", "        System.out.println(\"Comprobación terminada\");", "    }", "}"], ["Declara la clase.", "Inicia main.", "Guarda el porcentaje de batería.", "Compara el nivel con el umbral. El bloque se ejecuta si la comparación es true.", "Muestra el aviso únicamente dentro de la rama verdadera.", "Cierra el bloque del if.", "Esta salida se ejecuta tanto si la condición fue true como false.", "Cierra main.", "Cierra la clase."], [{ step: "Evaluación", values: "bateria=15; 15 < 20 → true", reason: "La condición es verdadera." }, { step: "Rama if", values: "se muestra el aviso", reason: "Java ejecuta el bloque condicionado." }, { step: "Continuación", values: "comprobación terminada", reason: "El flujo continúa después del if." }], ["Carga el dispositivo", "Comprobación terminada"], ["Escribir if (bateria < 20);: el punto y coma termina el if vacío; elimina ese ;.", "Confundir = y ==: dentro de una condición compara con ==.", "Olvidar llaves y añadir después otra línea: encierra el bloque desde el principio."], "Usa if para una acción opcional. Si necesitas definir ambos resultados, if-else comunica mejor la intención."),
  "Condicional if-else": entry("Construirás dos caminos excluyentes: uno para una condición verdadera y otro para la condición falsa.", ["if-else selecciona exactamente una de dos ramas. Java evalúa la condición una vez y ejecuta el bloque correspondiente.", "La rama else no necesita otra condición: representa todos los casos en los que el if fue falso. Esto evita repetir la condición y mantener dos reglas potencialmente inconsistentes.", "Comprueba los casos frontera: para edad >= 18, el valor 18 sí pertenece a la rama de acceso."], "Una puerta automática se abre si la tarjeta es válida; de lo contrario muestra un mensaje de rechazo.", ["public class Acceso {", "    public static void main(String[] args) {", "        int edad = 17;", "        if (edad >= 18) {", "            System.out.println(\"Acceso permitido\");", "        } else {", "            System.out.println(\"Acceso denegado\");", "        }", "    }", "}"], ["Declara la clase Acceso.", "Punto de entrada de la aplicación.", "Dato que se evaluará.", "Evalúa si la edad alcanza el límite inclusivo de 18.", "Rama true: solo se ejecuta si edad es 18 o mayor.", "Abre la alternativa cuando la condición del if es falsa.", "Rama false: informa que no se alcanza el límite.", "Cierra la estructura if-else.", "Cierra main.", "Cierra la clase."], [{ step: "Entrada", values: "edad=17", reason: "El dato se guarda en la variable." }, { step: "Condición", values: "17 >= 18 → false", reason: "La edad está por debajo del límite." }, { step: "Rama elegida", values: "else", reason: "Solo la alternativa falsa se ejecuta." }], ["Acceso denegado"], ["Usar > 18 cuando 18 también debe pasar: elige >= para incluir el límite.", "Escribir dos if independientes y ejecutar ambas ramas: usa else para que sean excluyentes.", "Poner una segunda condición en else: usa else if si realmente hay otro rango."], "Elige if-else cuando cada entrada debe producir uno de dos resultados alternativos."),
  "Condicionales else-if": entry("Clasificarás un valor entre varios intervalos con una cadena ordenada de condiciones mutuamente excluyentes.", ["Java evalúa una cadena else-if desde arriba. Cuando una condición es verdadera, ejecuta ese bloque y omite los restantes.", "El orden importa: coloca primero las reglas más específicas o los límites superiores adecuados. Si los intervalos se solapan, la primera condición verdadera gana.", "Termina con else cuando todos los casos posibles deben quedar cubiertos. Prueba valores en los extremos de cada intervalo."], "Un sistema de calificaciones compara una nota con los límites de sobresaliente, aprobado y suspenso.", ["public class Calificacion {", "    public static void main(String[] args) {", "        int nota = 7;", "        if (nota >= 9) {", "            System.out.println(\"Sobresaliente\");", "        } else if (nota >= 5) {", "            System.out.println(\"Aprobado\");", "        } else {", "            System.out.println(\"Suspenso\");", "        }", "    }", "}"], ["Declara la clase del ejemplo.", "Abre main.", "Guarda la nota entre cero y diez.", "Comprueba primero si alcanza nueve.", "Se ejecutaría solo para nota igual o superior a nueve.", "Solo se evalúa si la primera condición era falsa; comprueba el mínimo para aprobar.", "Se ejecuta para notas desde cinco hasta ocho.", "Cubre las notas que no han pasado ninguna condición anterior.", "Muestra el resultado para notas menores que cinco.", "Cierra la cadena de condiciones.", "Cierra main.", "Cierra la clase."], [{ step: "Primera condición", values: "7 >= 9 → false", reason: "Se continúa con el siguiente else-if." }, { step: "Segunda condición", values: "7 >= 5 → true", reason: "Se encuentra la primera rama válida." }, { step: "Fin", values: "Aprobado", reason: "Las ramas restantes se omiten." }], ["Aprobado"], ["Comprobar nota >= 5 antes que nota >= 9: la segunda rama haría inaccesible el sobresaliente.", "Olvidar validar el rango 0–10: entradas como 14 también llegarían a sobresaliente.", "Dejar valores sin rama ni else: añade una alternativa final cuando necesites cubrirlos."], "Usa else-if para rangos ordenados; para opciones discretas independientes considera switch."),
  "Operador ternario": entry("Expresarás una elección sencilla entre dos valores con la forma condición ? valorSiTrue : valorSiFalse.", ["El ternario evalúa una condición y produce uno de dos valores. Como produce un valor, se puede asignar a una variable o pasar a un método.", "Es apropiado para una decisión corta. No lo anides para reemplazar una cadena extensa de if-else: la legibilidad es más importante que reducir líneas.", "Los dos resultados deben ser compatibles con el tipo que se espera recibir."], "Una pantalla muestra el estado 'abierto' o 'cerrado' según si la tienda está atendiendo.", ["public class Ternario {", "    public static void main(String[] args) {", "        int edad = 20;", "        String acceso = edad >= 18 ? \"permitido\" : \"denegado\";", "        System.out.println(acceso);", "    }", "}"], ["Declara la clase del ejemplo.", "Inicia la aplicación.", "Guarda la edad.", "Si edad >= 18 es true, elige permitido; en caso contrario, elige denegado.", "Imprime el valor seleccionado.", "Cierra main.", "Cierra la clase."], [{ step: "Evaluar", values: "20 >= 18 → true", reason: "La condición selecciona la primera expresión." }, { step: "Asignar", values: "acceso='permitido'", reason: "La rama false no se evalúa." }, { step: "Salida", values: "permitido", reason: "println muestra la variable." }], ["permitido"], ["Intercambiar los dos resultados alrededor de ?: prueba ambos casos.", "Olvidar que el ternario devuelve un valor: cada rama debe producir una expresión compatible.", "Anidar ternarios largos: usa if-else para que la lógica sea legible."], "Úsalo para una selección breve que encaje en una sola lectura; para acciones extensas, usa if-else."),
  "Switch tradicional y moderno": entry("Elegirás una rama según un valor discreto y compararás el switch tradicional con la sintaxis de flechas moderna.", ["switch compara una expresión con etiquetas case. En la forma tradicional, break evita continuar accidentalmente en el siguiente caso.", "La forma moderna usa case valor -> y no necesita break. Una expresión switch puede devolver un valor; default cubre entradas no enumeradas.", "El tipo de selector y las etiquetas deben ser compatibles. No uses switch para comprobar intervalos; if-else es más apropiado."], "Un menú permite seleccionar una bebida mediante un número; cada opción lleva a una respuesta distinta.", ["public class Menu {", "    public static void main(String[] args) {", "        int opcion = 2;", "        String bebida = switch (opcion) {", "            case 1 -> \"Agua\";", "            case 2 -> \"Té\";", "            default -> \"Opción no disponible\";", "        };", "        System.out.println(bebida);", "    }", "}"], ["Declara la clase Menu.", "Punto de entrada.", "Guarda la opción seleccionada.", "Inicia una expresión switch cuyo resultado se asignará a bebida.", "Si la opción vale 1, produce Agua.", "Si vale 2, produce Té.", "Cubre el resto de valores.", "Cierra la expresión switch.", "Imprime el valor obtenido.", "Cierra main.", "Cierra la clase."], [{ step: "Selector", values: "opcion=2", reason: "El switch compara el selector con las etiquetas." }, { step: "Coincidencia", values: "case 2", reason: "Se elige la expresión Té." }, { step: "Resultado", values: "bebida='Té'", reason: "La expresión asigna el texto producido." }], ["Té"], ["Olvidar break en switch tradicional: añade break en cada caso que deba terminar.", "No cubrir opciones desconocidas: incluye default.", "Usar switch para rangos como nota >= 5: usa if-else para intervalos."], "Utiliza switch con menús y categorías discretas. Elige flechas modernas para evitar el fall-through accidental."),
  "Bucle while": entry("Repetirás instrucciones mientras una condición siga siendo verdadera y aprenderás a evitar ciclos infinitos.", ["while comprueba la condición antes de ejecutar el cuerpo. Si inicialmente es falsa, puede que el bloque no se ejecute ninguna vez.", "El cuerpo debe avanzar hacia que la condición deje de cumplirse. Normalmente se actualiza un contador o se lee una nueva entrada en cada vuelta.", "Comprueba la condición de parada con casos pequeños y asegúrate de que todos los caminos cambian el estado necesario."], "Un ascensor sigue subiendo mientras queden plantas por recorrer; antes de cada planta comprueba si ya llegó al destino.", ["public class Mientras {", "    public static void main(String[] args) {", "        int planta = 1;", "        while (planta <= 3) {", "            System.out.println(\"Planta \" + planta);", "            planta++;", "        }", "    }", "}"], ["Declara la clase del ejemplo.", "Inicia main.", "Inicializa el contador antes de evaluar la condición.", "Comprueba el límite antes de cada vuelta.", "Muestra el valor de la iteración actual.", "Incrementa planta para acercarse al final del bucle.", "Cierra el cuerpo que se repite.", "Cierra main.", "Cierra la clase."], [{ step: "Comprobar 1", values: "planta=1; 1<=3 true", reason: "Se entra al cuerpo." }, { step: "Primera vuelta", values: "imprime 1; planta pasa a 2", reason: "La actualización ocurre dentro del bloque." }, { step: "Última comprobación", values: "planta=4; 4<=3 false", reason: "La condición falsa termina el bucle." }], ["Planta 1", "Planta 2", "Planta 3"], ["No modificar planta: la condición nunca cambia y el bucle puede ser infinito.", "Usar < en vez de <= sin decidir el límite: comprueba si el último valor debe incluirse.", "Esperar una iteración obligatoria: while puede ejecutarse cero veces."], "Elige while cuando el número de repeticiones depende de una condición que se comprueba antes."),
  "Bucle do-while": entry("Usarás do-while cuando el bloque tenga que ejecutarse al menos una vez antes de comprobar la condición.", ["do-while ejecuta el cuerpo y después evalúa la condición. Si es verdadera, vuelve al inicio; si es falsa, sale.", "La condición termina con punto y coma, una diferencia importante respecto a while. Esta estructura resulta útil para mostrar un menú al menos una vez.", "Asegúrate de que el estado de la condición se actualiza antes de comprobarla de nuevo."], "Un cajero muestra el menú una primera vez y solo lo vuelve a mostrar si el cliente no ha elegido salir.", ["public class Repetir {", "    public static void main(String[] args) {", "        int intento = 1;", "        do {", "            System.out.println(\"Intento \" + intento);", "            intento++;", "        } while (intento <= 3);", "    }", "}"], ["Declara la clase.", "Punto de entrada de la aplicación.", "Inicializa el contador de intentos.", "Empieza el cuerpo que se ejecutará al menos una vez.", "Muestra el número de intento actual.", "Avanza el contador antes de evaluar la condición.", "Continúa si el contador todavía no ha superado tres; fíjate en el ; final.", "Cierra main.", "Cierra la clase."], [{ step: "Cuerpo 1", values: "intento=1; luego 2", reason: "El cuerpo ocurre antes de la condición." }, { step: "Condición", values: "2<=3 true", reason: "Se repite por segunda vez." }, { step: "Cierre", values: "intento=4; 4<=3 false", reason: "Después de la tercera vuelta termina." }], ["Intento 1", "Intento 2", "Intento 3"], ["Olvidar el punto y coma después de while(...): do-while lo requiere.", "Creer que el cuerpo puede no ejecutarse: siempre hay una primera vuelta.", "No actualizar la condición dentro del cuerpo: el ciclo puede no terminar."], "Úsalo para menús o validaciones que deben solicitarse al menos una vez; si no, while expresa mejor la condición previa."),
  "Bucle for": entry("Controlarás una repetición con contador, condición de continuación y actualización concentrados en la cabecera del for.", ["La cabecera for tiene tres partes: inicialización, condición y actualización. Primero inicializa; antes de cada iteración evalúa la condición; al terminar el cuerpo actualiza.", "En este ejemplo el contador vale sucesivamente 1, 2, 3, 4 y 5. Cuando vale 6, la condición falla y el bucle termina.", "La variable declarada en la cabecera solo existe dentro del bucle. El número de vueltas puede contarse a partir de los valores que hacen verdadera la condición."], "Recorrer los asientos numerados del 1 al 5 es un recorrido con inicio conocido y un avance regular.", ["public class Cuenta {", "    public static void main(String[] args) {", "        for (int vuelta = 1; vuelta <= 5; vuelta++) {", "            System.out.println(\"Vuelta \" + vuelta);", "        }", "    }", "}"], ["Declara la clase Cuenta.", "Punto de entrada.", "Inicializa vuelta a 1; comprueba vuelta<=5 antes de entrar; suma uno al terminar cada cuerpo.", "Imprime el número correspondiente a la vuelta actual.", "Cierra el cuerpo que se repite.", "Cierra main.", "Cierra la clase."], [{ step: "Inicialización", values: "vuelta=1", reason: "Se ejecuta una sola vez." }, { step: "Comprobaciones válidas", values: "1, 2, 3, 4, 5", reason: "Cada valor satisface <=5 y genera una salida." }, { step: "Última comprobación", values: "vuelta=6; 6<=5 false", reason: "El contador ya superó el límite; finaliza." }], ["Vuelta 1", "Vuelta 2", "Vuelta 3", "Vuelta 4", "Vuelta 5"], ["Usar vuelta < 5 cuando se desean cinco valores desde uno: imprime solo cuatro.", "Añadir un ; después de la cabecera: el bucle queda vacío.", "Cambiar el contador dentro del cuerpo además del incremento: puede saltar valores."], "Prefiere for para recorridos con inicio, fin y paso conocidos."),
  "Bucles anidados": entry("Analizarás un for exterior que recorre semanas y otro interior que vuelve a recorrer todos los días por cada semana.", ["Un bucle anidado es un bucle dentro del bloque de otro. El exterior controla las rondas grandes; el interior completa todas sus iteraciones antes de que el exterior avance.", "semana empieza en 1, continúa mientras semana<=3 y aumenta una unidad al final de cada ronda. El día empieza en 1 cada vez que el flujo vuelve a la declaración del for interior; su variable se crea de nuevo en ese ámbito.", "El exterior comprueba 4 veces (tres válidas y una falsa); el interior comprueba 6 veces por semana (cinco válidas y una falsa), por lo que su cuerpo se ejecuta 3×5=15 veces. Cada vuelta interior termina antes del siguiente incremento de semana."], "Organizar un calendario con tres semanas y cinco días hábiles: el bucle exterior cambia de semana y el interior visita cada día.", ["public class BuclesAnidados {", "    public static void main(String[] args) {", "        for (int semana = 1; semana <= 3; semana++) {", "            System.out.println(\"Semana \" + semana);", "            for (int dia = 1; dia <= 5; dia++) {", "                System.out.println(\"Día \" + dia);", "            }", "        }", "    }", "}"], ["Declara la clase y el nombre del archivo será BuclesAnidados.java.", "Java empieza la aplicación en main.", "Inicializa semana=1 una vez; comprueba <=3 antes de cada semana; semana++ ocurre cuando termina por completo el bloque exterior.", "Anuncia la semana antes de recorrer sus días.", "Cada vez que empieza una semana se declara dia=1; mientras dia<=5, el contador avanza al final de cada día.", "Muestra el día actual; esta línea ocurre cinco veces por semana.", "Al cerrar este bloque, el for interior ha acabado; entonces el exterior avanza semana.", "Cierra el bloque del bucle exterior.", "Cierra main.", "Cierra la clase."], [{ step: "Semana 1 · día 1", values: "semana=1, dia=1", reason: "Ambas condiciones permiten ejecutar el cuerpo interior." }, { step: "Semana 1 · día 5", values: "semana=1, dia=5", reason: "Última iteración interior; después dia pasa a 6 y sale." }, { step: "Cambio de semana", values: "semana=2, dia vuelve a 1", reason: "La declaración interior se ejecuta de nuevo y reinicia dia." }, { step: "Final", values: "3 semanas × 5 días = 15 líneas de día", reason: "Al acabar semana 3, semana pasa a 4 y la condición exterior falla." }], ["Semana 1", "Día 1", "Día 2", "Día 3", "Día 4", "Día 5", "Semana 2", "Día 1", "Día 2", "Día 3", "Día 4", "Día 5", "Semana 3", "Día 1", "Día 2", "Día 3", "Día 4", "Día 5"], ["Pensar que el interior y el exterior avanzan a la vez: el interior termina todas sus vueltas primero.", "Declarar dia antes del bucle y olvidar reiniciarlo: al empezar otra semana debe volver a 1.", "Contar solo 3+5=8 ejecuciones: las cinco iteraciones internas ocurren en cada una de las tres semanas.", "Mover semana++ al interior: el contador exterior cambiaría en el momento equivocado."], "Usa bucles anidados para datos en filas y columnas o combinaciones. Si el producto de iteraciones crece mucho, revisa el coste total."),
  "Contadores": entry("Contarás eventos con una variable entera y decidirás con cuidado cuándo debe incrementarse.", ["Un contador registra cuántas veces ocurre algo. Se inicializa antes del recorrido y se incrementa solo cuando el evento que nos interesa sucede.", "Si se incrementa siempre, cuenta iteraciones; dentro de una condición puede contar solo valores que cumplen un criterio.", "Al terminar, el contador representa el número de casos registrados, no necesariamente el valor máximo recorrido."], "En una caja, el contador de productos defectuosos solo aumenta cuando la inspección detecta uno.", ["public class Contador {", "    public static void main(String[] args) {", "        int defectuosos = 0;", "        for (int pieza = 1; pieza <= 5; pieza++) {", "            if (pieza == 2 || pieza == 5) {", "                defectuosos++;", "            }", "        }", "        System.out.println(defectuosos);", "    }", "}"], ["Declara la clase Contador.", "Punto de entrada.", "Inicializa el conteo de defectos en cero.", "Visita cinco piezas.", "Selecciona las piezas 2 y 5 como defectuosas.", "Aumenta el contador solo cuando se cumple la regla.", "Cierra el if.", "Cierra el recorrido.", "Muestra el número de piezas registradas como defectuosas.", "Cierra main.", "Cierra la clase."], [{ step: "Inicio", values: "defectuosos=0", reason: "Todavía no se inspeccionó ninguna pieza." }, { step: "Pieza 2", values: "condición=true; defectuosos=1", reason: "Se registra un evento." }, { step: "Pieza 5", values: "condición=true; defectuosos=2", reason: "Se registra otro evento." }, { step: "Fin", values: "defectuosos=2", reason: "Las demás piezas no modifican el conteo." }], ["2"], ["Inicializar en uno sin incluir un evento inicial: el conteo queda desplazado.", "Incrementar fuera del if: contaría todas las piezas, no solo las defectuosas.", "Mostrar el último número de pieza pensando que es la cantidad: cuenta eventos explícitamente."], "Usa contadores para número de intentos, coincidencias, elementos válidos o iteraciones."),
  "Acumuladores": entry("Acumularás resultados parciales y verás cómo una suma se construye iteración tras iteración.", ["Un acumulador combina el valor actual con cada nuevo dato, por ejemplo suma = suma + dato. Para una suma suele comenzar en cero; para un producto, en uno.", "En una suma filtrada, la condición decide qué valores se añaden. El acumulador debe conservar el resultado parcial entre vueltas.", "Distingue acumulador de contador: el contador aumenta típicamente en una unidad; el acumulador incorpora datos de magnitud variable."], "En una hucha, el saldo se actualiza añadiendo cada moneda nueva al importe anterior.", ["public class Acumulador {", "    public static void main(String[] args) {", "        int suma = 0;", "        for (int numero = 1; numero <= 4; numero++) {", "            suma = suma + numero;", "        }", "        System.out.println(suma);", "    }", "}"], ["Declara la clase Acumulador.", "Punto de entrada.", "Inicializa la suma al elemento neutro de la suma: cero.", "Recorre los valores 1, 2, 3 y 4.", "Añade el valor actual al subtotal guardado y reemplaza suma.", "Cierra el bucle.", "Muestra el resultado acumulado.", "Cierra main.", "Cierra la clase."], [{ step: "Inicial", values: "suma=0", reason: "No se han añadido elementos." }, { step: "numero=1", values: "suma=0+1=1", reason: "Primer subtotal." }, { step: "numero=2", values: "suma=1+2=3", reason: "Se conserva el subtotal previo." }, { step: "numero=3 y 4", values: "3+3=6; 6+4=10", reason: "Cada iteración incorpora un elemento." }], ["10"], ["Empezar una suma en uno: añade un uno indebido.", "Reiniciar suma dentro del bucle: se perderían los subtotales anteriores.", "Usar += sobre una variable no inicializada: inicialízala antes del recorrido."], "Usa un acumulador para sumas, productos, concatenaciones o resúmenes construidos en varias iteraciones."),
  "Banderas booleanas": entry("Representarás con un booleano si un evento ya ocurrió o una condición sigue siendo posible.", ["Una bandera es una variable booleana que cambia de estado cuando sucede algo relevante. Por ejemplo, encontrado pasa de false a true al detectar un elemento.", "El nombre debe describir el significado del estado, no la mecánica. Se puede detener un recorrido cuando la bandera se activa o continuar para contar otras coincidencias.", "Inicializa la bandera según el estado inicial y revisa dónde cambia; si nunca cambia, su condición no modifica el flujo."], "Un testigo de una búsqueda levanta una bandera al encontrar el libro solicitado.", ["public class Bandera {", "    public static void main(String[] args) {", "        boolean encontrado = false;", "        for (int numero = 1; numero <= 5; numero++) {", "            if (numero == 3) {", "                encontrado = true;", "            }", "        }", "        System.out.println(encontrado);", "    }", "}"], ["Declara la clase del ejemplo.", "Inicia main.", "Al principio todavía no se ha encontrado el valor.", "Recorre los números de uno a cinco.", "Comprueba si el valor actual es el buscado.", "Cambia la bandera cuando encuentra el número tres.", "Cierra la condición.", "Cierra el bucle.", "Muestra el estado final de la búsqueda.", "Cierra main.", "Cierra la clase."], [{ step: "Inicio", values: "encontrado=false", reason: "La búsqueda aún no empezó." }, { step: "numero=1 y 2", values: "encontrado=false", reason: "No coinciden con el objetivo." }, { step: "numero=3", values: "encontrado=true", reason: "La condición activa la bandera." }, { step: "Fin", values: "encontrado=true", reason: "El estado persiste fuera del bucle." }], ["true"], ["No reiniciar la bandera para una nueva búsqueda: vuelve al estado inicial antes del recorrido.", "Usar una String 'sí/no' como estado: boolean expresa exactamente dos estados.", "Cambiarla cuando el evento no ocurrió: coloca la asignación dentro de la condición adecuada."], "Usa banderas para recordar eventos entre iteraciones, como encontrado, válido o debeContinuar."),
  "Instrucción break": entry("Interrumpirás el bucle actual al cumplirse una condición y distinguirás break de una condición normal de salida.", ["break termina inmediatamente el bucle o switch más cercano. El flujo continúa en la primera instrucción que aparece después de ese bloque.", "En una búsqueda, break evita seguir recorriendo una vez que ya se encontró el elemento. No termina automáticamente los bucles exteriores si hay anidamiento.", "Una condición de bucle bien escrita suele ser más expresiva; usa break cuando el momento de parada depende de un evento detectado dentro del cuerpo."], "Dejas de buscar en una estantería en cuanto encuentras el libro, aunque queden libros por revisar.", ["public class Detener {", "    public static void main(String[] args) {", "        for (int numero = 1; numero <= 5; numero++) {", "            if (numero == 3) {", "                break;", "            }", "            System.out.println(numero);", "        }", "        System.out.println(\"Fin\");", "    }", "}"], ["Declara la clase Detener.", "Punto de entrada.", "Inicia un recorrido de cinco números.", "Comprueba si se llegó al número de parada.", "Termina de inmediato el for más cercano.", "Cierra el if.", "Solo se imprime para las vueltas anteriores a la parada.", "Cierra el bucle.", "La ejecución continúa aquí después de break.", "Cierra main.", "Cierra la clase."], [{ step: "numero=1", values: "1 != 3; imprime 1", reason: "No se ejecuta break." }, { step: "numero=2", values: "2 != 3; imprime 2", reason: "El bucle continúa." }, { step: "numero=3", values: "break", reason: "El bucle termina antes de imprimir 3." }, { step: "Después", values: "Fin", reason: "El flujo continúa tras el bloque for." }], ["1", "2", "Fin"], ["Pensar que break termina toda la aplicación: solo termina la estructura más cercana.", "Ponerlo fuera de un bucle o switch: el compilador lo rechazará.", "Usarlo para ocultar una condición de salida confusa: explica qué evento justifica la parada."], "Úsalo en búsquedas o menús cuando se detecte una condición de salida dentro del cuerpo."),
  "Instrucción continue": entry("Omitirás el resto de la iteración actual con continue y dejarás que el bucle pase a su siguiente vuelta.", ["continue no termina el bucle: salta el resto del cuerpo actual. En un for, después ejecuta la actualización y vuelve a comprobar la condición.", "Resulta útil para descartar elementos que no deben procesarse y mantener el camino principal menos anidado.", "Asegúrate de que cualquier actualización necesaria para terminar el bucle no quede saltada. En while, si el contador se incrementa después de continue, puede aparecer un ciclo infinito."], "En una lista de pedidos, se omite el pedido cancelado y se continúa revisando los siguientes.", ["public class Saltar {", "    public static void main(String[] args) {", "        for (int numero = 1; numero <= 5; numero++) {", "            if (numero == 3) {", "                continue;", "            }", "            System.out.println(numero);", "        }", "    }", "}"], ["Declara la clase Saltar.", "Abre main.", "Recorre números del uno al cinco.", "Detecta el valor que se quiere omitir.", "Salta el resto del cuerpo de esta vuelta, pero no termina el bucle.", "Cierra la condición.", "Se ejecuta para todos los valores excepto el omitido.", "Cierra el for.", "Cierra main.", "Cierra la clase."], [{ step: "numero=2", values: "condición falsa; imprime 2", reason: "La iteración sigue su flujo habitual." }, { step: "numero=3", values: "continue; omite println", reason: "El for incrementa numero a 4 después del salto." }, { step: "numero=4", values: "imprime 4", reason: "La siguiente iteración sí se procesa." }], ["1", "2", "4", "5"], ["Creer que continue termina el bucle: usa break para salir.", "Saltar un incremento manual en while: actualiza antes del continue o reestructura el bucle.", "Usar continue sin explicar el caso descartado: nombra claramente la condición."], "Úsalo cuando quieras ignorar una iteración y procesar el resto; break corresponde a una salida completa."),
  "Instrucción return": entry("Comprenderás cómo return termina un método y, cuando corresponde, entrega un valor al código que lo llamó.", ["return finaliza inmediatamente el método actual. En un método void se escribe return; sin valor; en uno no-void se devuelve un valor compatible con el tipo declarado.", "El llamador puede usar el valor devuelto en una asignación o expresión. Las instrucciones situadas después de un return incondicional no se ejecutan y algunas provocan error de código inalcanzable.", "En main, return termina la ejecución de main; no equivale a break, que solo termina el bucle o switch más próximo."], "Al terminar una llamada de atención, la persona regresa a quien la llamó con la respuesta solicitada.", ["public class Retorno {", "    public static void main(String[] args) {", "        int resultado = doble(4);", "        System.out.println(resultado);", "    }", "    static int doble(int numero) {", "        return numero * 2;", "    }", "}"], ["Declara la clase Retorno.", "Inicia el método principal.", "Llama al método doble y guarda su valor de retorno.", "Imprime el valor recibido.", "Cierra main.", "Declara doble: recibe int y promete devolver int.", "return calcula y entrega el doble; la ejecución de doble termina aquí.", "Cierra el método doble.", "Cierra la clase."], [{ step: "Llamada", values: "doble(4), numero=4", reason: "El argumento se asigna al parámetro." }, { step: "return", values: "4×2=8", reason: "El método termina y envía 8 al llamador." }, { step: "Después de la llamada", values: "resultado=8", reason: "main recibe el valor y continúa." }], ["8"], ["Omitir return en un método int: todos los caminos deben devolver un int.", "Poner una instrucción necesaria después de return: nunca se ejecutará.", "Confundir return con println: return entrega un valor; println solo lo muestra."], "Usa return para producir resultados o terminar temprano un método cuando su trabajo ya concluyó."),
  "Métodos y parámetros": entry("Dividirás el programa en métodos reutilizables, pasarás argumentos a parámetros y devolverás un resultado calculado.", ["La declaración de un método indica modificadores, tipo de retorno, nombre y parámetros. Los parámetros son variables locales que reciben datos al llamar al método.", "El argumento es el valor que se pasa en la llamada. El tipo y número de argumentos deben corresponder a la firma del método.", "Un método debería tener una responsabilidad clara. static permite llamar al método desde main sin crear un objeto en este ejemplo inicial."], "Una máquina de zumo recibe cierta cantidad de naranjas, las procesa con una receta y devuelve una jarra como resultado.", ["public class Metodos {", "    public static void main(String[] args) {", "        int total = sumar(3, 4);", "        System.out.println(total);", "    }", "    static int sumar(int primero, int segundo) {", "        int resultado = primero + segundo;", "        return resultado;", "    }", "}"], ["Declara la clase Metodos.", "Abre el punto de entrada.", "Llama a sumar con los argumentos 3 y 4; guarda lo que devuelve.", "Muestra el total.", "Cierra main.", "Declara un método estático que recibe dos parámetros int y devuelve int.", "Suma los parámetros dentro de una variable local.", "Entrega el resultado al punto de llamada y termina el método.", "Cierra sumar.", "Cierra la clase."], [{ step: "Argumentos", values: "3 → primero; 4 → segundo", reason: "Los valores se enlazan en el orden de la firma." }, { step: "Cálculo local", values: "resultado=3+4=7", reason: "El método procesa sus parámetros." }, { step: "Retorno", values: "total=7", reason: "El valor devuelto se asigna al llamador." }], ["7"], ["Devolver void y escribir return valor: el tipo de retorno debe coincidir.", "Cambiar el orden de los argumentos: Java los asigna posicionalmente.", "Imprimir dentro del método cuando se necesita reutilizar el cálculo: devuelve el dato y deja la salida al llamador."], "Crea métodos cuando un cálculo se repite o cuando nombrar una operación facilita entender el programa."),
  "Cláusulas guardián": entry("Validarás los parámetros al principio del método y usarás return para impedir que datos inválidos alcancen el cálculo principal.", ["Una cláusula guardián es una condición de salida temprana que protege el resto del método. Si semanas no es válida, muestra el mensaje y return termina esa llamada inmediatamente.", "Después se comprueba dias. Esta segunda comprobación solo ocurre si las semanas pasaron la primera; el cálculo final solo se alcanza cuando las dos entradas son positivas.", "Este patrón reduce niveles de if anidados y deja visible el camino válido. return no pausa ni vuelve al principio: abandona el método actual."], "En recepción revisan la identificación antes de dejarte pasar; si falta, el proceso se detiene ahí y no se realizan los pasos posteriores.", ["public class Validar {", "    public static void main(String[] args) {", "        mostrarDias(3, 5);", "    }", "    static void mostrarDias(int semanas, int dias) {", "        if (semanas <= 0) {", "            System.out.println(\"Introduce las semanas\");", "            return;", "        }", "        if (dias <= 0) {", "            System.out.println(\"Introduce los días\");", "            return;", "        }", "        System.out.println(\"Datos correctos\");", "    }", "}"], ["Declara la clase Validar.", "Punto de entrada del programa.", "Llama al método con tres semanas y cinco días.", "Cierra main.", "Declara un método void con dos parámetros enteros.", "Primera guarda: rechaza semanas no positivas.", "Explica el error de entrada.", "return termina mostrarDias; no se evalúan las líneas posteriores de esta llamada.", "Cierra el primer if.", "Segunda guarda: solo se evalúa si semanas fue válida.", "Explica el error en el segundo parámetro.", "Termina el método cuando dias no es válido.", "Cierra el segundo if.", "Solo se alcanza cuando ambas validaciones pasan.", "Cierra mostrarDias.", "Cierra la clase."], [{ step: "Entrada válida", values: "semanas=3, dias=5", reason: "3<=0 es false y 5<=0 es false." }, { step: "Primera guarda", values: "semanas=0 → return", reason: "Termina antes de revisar dias." }, { step: "Segunda guarda", values: "semanas=3, dias=-1 → return", reason: "La primera validación pasa; la segunda detiene el método." }], ["Datos correctos"], ["Olvidar return tras mostrar el error: el método continúa y puede imprimir un segundo mensaje.", "Validar después del cálculo: comprueba primero las precondiciones.", "Anidar todo el método dentro de if válidos: las guardas tempranas simplifican el camino correcto."], "Usa cláusulas guardián para parámetros inválidos, estados no permitidos o casos límite que deben terminar pronto."),
  "Excepciones y try-catch-finally": entry("Responderás a errores excepcionales con try-catch y ejecutarás limpieza con finally cuando sea necesaria.", ["El bloque try contiene instrucciones que pueden lanzar una excepción. Java busca un catch cuyo tipo sea compatible con la excepción producida.", "finally se ejecuta al salir del try/catch, tanto si hubo excepción como si no, salvo terminaciones abruptas excepcionales. Para recursos, try-with-resources suele ser más seguro.", "Captura tipos concretos que sabes manejar. No silencies una excepción con un catch vacío: informa o recupera el estado de forma razonable."], "Si una herramienta falla al procesar un pedido, se muestra una explicación y aun así se devuelve la herramienta al almacén en finally.", ["public class Captura {", "    public static void main(String[] args) {", "        int divisor = 0;", "        try {", "            System.out.println(10 / divisor);", "        } catch (ArithmeticException error) {", "            System.out.println(\"No se puede dividir entre cero\");", "        } finally {", "            System.out.println(\"Fin del cálculo\");", "        }", "    }", "}"], ["Declara la clase Captura.", "Abre main.", "Prepara un divisor cero para provocar la excepción.", "Inicia la región que puede fallar.", "La división entera entre cero lanza ArithmeticException; esta println no termina normalmente.", "Captura ese tipo concreto de error y lo enlaza con error.", "Muestra una respuesta comprensible para el usuario.", "finally se ejecuta al terminar el manejo.", "Muestra que se ha terminado el intento de cálculo.", "Cierra finally.", "Cierra main.", "Cierra la clase."], [{ step: "Entrada", values: "divisor=0", reason: "Se fija el caso límite que causará un fallo aritmético." }, { step: "try", values: "10/0 → ArithmeticException", reason: "La ejecución salta a un catch compatible." }, { step: "catch y finally", values: "mensaje de error; luego cierre", reason: "El catch maneja la excepción y finally se ejecuta al final." }], ["No se puede dividir entre cero", "Fin del cálculo"], ["Capturar Exception y ocultar todo: captura el tipo específico que sabes resolver.", "Dejar el catch vacío: la persona no sabrá por qué falló.", "Creer que finally no se ejecuta al haber catch: normalmente se ejecuta después del manejo."], "Usa excepciones para fallos excepcionales; no sustituyas con ellas una validación normal y esperada."),
  "InputMismatchException": entry("Reconocerás el error de Scanner cuando la entrada no coincide con el tipo solicitado y recuperarás el estado para volver a pedirla.", ["nextInt espera un token que pueda convertirse a entero. Si el usuario escribe letras o un decimal con formato incompatible, Scanner lanza InputMismatchException.", "Tras capturarla, el token incorrecto sigue pendiente; llama a next para consumirlo antes de volver a pedir la entrada, o el programa repetirá el mismo error.", "La validación de entrada forma parte de una interacción robusta. Este ejemplo limita el ejercicio a una lectura y un mensaje de error."], "Una báscula que solo admite kilos numéricos rechaza una palabra y pide introducir de nuevo un valor con formato válido.", ["import java.util.InputMismatchException;", "import java.util.Scanner;", "public class EntradaSegura {", "    public static void main(String[] args) {", "        Scanner teclado = new Scanner(System.in);", "        System.out.print(\"Introduce una edad: \" );", "        try {", "            int edad = teclado.nextInt();", "            System.out.println(\"Edad: \" + edad);", "        } catch (InputMismatchException error) {", "            System.out.println(\"La edad debe ser un número entero\");", "            teclado.next();", "        }", "        teclado.close();", "    }", "}"], ["Importa la excepción específica de Scanner.", "Importa la clase Scanner para leer la consola.", "Declara la clase EntradaSegura.", "Punto de entrada.", "Prepara el lector de entrada.", "Solicita un valor entero.", "Empieza el bloque que puede fallar.", "Lee un token como entero; texto no numérico provoca InputMismatchException.", "Muestra el dato solo cuando se leyó correctamente.", "Captura la excepción que produce Scanner al no poder convertir el token.", "Explica el formato esperado.", "Consume el token inválido para que no permanezca pendiente.", "Cierra el catch.", "Libera el lector al terminar.", "Cierra main.", "Cierra la clase."], [{ step: "Entrada válida", values: "19 → edad=19", reason: "nextInt convierte el token y se ejecuta el try." }, { step: "Entrada inválida", values: "hola → excepción", reason: "El catch específico recibe el fallo de conversión." }, { step: "Recuperación", values: "teclado.next() consume 'hola'", reason: "Eliminar el token evita leerlo repetidamente." }], ["Introduce una edad: 19", "Edad: 19"], ["Capturar InputMismatchException sin consumir el token: la próxima lectura vuelve a fallar con el mismo dato.", "Capturar una excepción demasiado general: usa la clase concreta de Scanner.", "Cerrar Scanner antes de terminar otras lecturas: conserva el lector mientras la aplicación lo necesite."], "Úsala al leer datos tipados con Scanner; para programas completos combina validación y un bucle de reintento."),
  "ArithmeticException": entry("Identificarás errores aritméticos como la división entera entre cero y decidirás si validar o capturar el caso.", ["La división de enteros entre cero lanza ArithmeticException durante la ejecución. En cambio, una división de double por cero puede producir infinito o NaN según la operación.", "Si el cero es un dato normal que se puede prever, comprobarlo antes de dividir suele ser más claro que usar excepciones como flujo habitual.", "El catch permite explicar el error y mantener el programa en control. No conviertas silenciosamente un resultado indefinido en un número cualquiera."], "Una calculadora comprueba que el divisor no sea cero antes de completar una operación.", ["public class DivisionSegura {", "    public static void main(String[] args) {", "        int dividendo = 20;", "        int divisor = 0;", "        if (divisor == 0) {", "            System.out.println(\"El divisor no puede ser cero\");", "        } else {", "            System.out.println(dividendo / divisor);", "        }", "    }", "}"], ["Declara la clase de división.", "Punto de entrada.", "Guarda el número que se dividirá.", "Guarda el divisor, cero para probar el caso límite.", "Comprueba el caso inválido antes de ejecutar la operación.", "Informa del problema sin provocar la excepción.", "Si el divisor no es cero, entra en la rama alternativa.", "Realiza la división solo después de validar el divisor.", "Cierra if-else.", "Cierra main.", "Cierra la clase."], [{ step: "Datos", values: "dividendo=20, divisor=0", reason: "Los valores se preparan antes de la condición." }, { step: "Validar", values: "divisor==0 → true", reason: "Se elige el mensaje y se evita la división." }, { step: "Resultado", values: "sin división", reason: "La rama else queda omitida." }], ["El divisor no puede ser cero"], ["Capturar ArithmeticException como única validación: si el cero es esperable, el if comunica mejor la regla.", "Dividir int y esperar Infinity: la división entera lanza excepción.", "Dejar fuera el caso divisor cero: verifica valores frontera antes del cálculo."], "Valida cuando conoces la regla; captura la excepción si el error puede surgir de una operación no controlada."),
  "Crear y lanzar excepciones": entry("Crearás una excepción con throw para comunicar que una entrada incumple una regla del programa.", ["throw lanza un objeto de excepción y transfiere el control al manejador compatible más cercano. Una excepción puede incluir un mensaje que describa el problema.", "IllegalArgumentException es una excepción no comprobada adecuada cuando un método recibe un argumento que viola su contrato.", "No lances excepciones para valores inválidos que forman parte del uso normal sin motivo; documenta qué condición se espera y deja que quien llama decida cómo responder."], "Una máquina expendedora rechaza una cantidad negativa porque no representa una entrada válida para el precio.", ["public class ValidarPrecio {", "    static double conDescuento(double precio) {", "        if (precio < 0) {", "            throw new IllegalArgumentException(\"El precio no puede ser negativo\");", "        }", "        return precio * 0.9;", "    }", "    public static void main(String[] args) {", "        System.out.println(conDescuento(10));", "    }", "}"], ["Declara la clase que define la validación.", "Declara un método que recibe el precio y devuelve double.", "Comprueba la precondición del método.", "Crea y lanza una excepción descriptiva; no se ejecuta el retorno normal.", "Cierra la guarda.", "Si el precio es válido, calcula un descuento del diez por ciento.", "Cierra el método.", "Punto de entrada del programa.", "Llama con 10 y muestra el resultado; una llamada con -1 propagaría la excepción.", "Cierra main.", "Cierra la clase."], [{ step: "Caso válido", values: "precio=10; 10<0 false", reason: "Se permite alcanzar el cálculo." }, { step: "Retorno", values: "10×0.9=9.0", reason: "El método entrega el valor descontado." }, { step: "Caso inválido alternativo", values: "precio=-1 → throw", reason: "La excepción interrumpe el método y notifica al llamador." }], ["9.0"], ["Escribir throw sin construir una excepción: throw necesita un objeto Throwable.", "Olvidar new al crear la excepción: usa new IllegalArgumentException(...).", "Capturar y ocultar el error de inmediato: deja que se gestione donde se pueda dar una respuesta útil."], "Úsala para expresar incumplimientos de contrato o fallos excepcionales; documenta la condición de lanzamiento."),
  "Estilo y Javadoc": entry("Aplicarás convenciones de nombres, formato y documentación para que otra persona pueda leer y utilizar tus métodos.", ["Las convenciones no cambian el resultado, pero reducen la carga de lectura. Clases usan UpperCamelCase; métodos y variables suelen usar lowerCamelCase.", "Mantén una indentación uniforme, una instrucción por línea y nombres que expliquen intención. Las constantes compartidas static final suelen escribirse en MAYÚSCULAS.", "Javadoc documenta propósito, parámetros, retorno y excepciones. El comentario debe mantenerse coherente con la implementación."], "Una receta ordenada con nombres claros y medidas uniformes es más fácil de repetir que una hoja con abreviaturas inconsistentes.", ["/**", " * Calcula el área de un rectángulo.", " * @param ancho medida horizontal positiva", " * @param alto medida vertical positiva", " * @return el área calculada", " */", "public class Rectangulo {", "    static double area(double ancho, double alto) {", "        return ancho * alto;", "    }", "    public static void main(String[] args) {", "        System.out.println(area(4, 3));", "    }", "}"], ["Abre el comentario Javadoc asociado a la clase.", "Resume la intención en un verbo claro.", "Describe el primer parámetro y su expectativa.", "Describe el segundo parámetro.", "Indica qué valor devuelve el método.", "Cierra Javadoc.", "Declara una clase con nombre UpperCamelCase.", "Usa un nombre lowerCamelCase y parámetros descriptivos.", "Devuelve el producto de las dos dimensiones.", "Cierra el método.", "Punto de entrada.", "Llama al método con ancho 4 y alto 3; muestra el retorno.", "Cierra main.", "Cierra la clase."], [{ step: "Llamada", values: "area(4,3)", reason: "Los argumentos se vinculan a ancho y alto." }, { step: "Calcular", values: "4×3=12", reason: "La operación devuelve el área." }, { step: "Salida", values: "12.0", reason: "La firma usa double y se muestra el resultado." }], ["12.0"], ["Usar nombres como x para dimensiones: elige ancho y alto para aclarar el papel.", "Documentar un tipo de retorno incorrecto: sincroniza @return con la firma actual.", "Mezclar indentación o escribir varias instrucciones en una línea: aplica un formato consistente."], "Aplica estas convenciones desde el primer programa; un formato automático ayuda, pero no reemplaza buenos nombres."),
  "Pruebas y aserciones": entry("Comprobarás una relación esperada entre entradas y salidas con pruebas pequeñas y aserciones.", ["Una prueba ejecuta el código con un caso conocido y compara el resultado real con el esperado. Conviene incluir casos normales, límites y valores especiales.", "assert expresa una condición que debería ser verdadera. En Java las aserciones pueden estar desactivadas por defecto y se habilitan con -ea; para un curso inicial, el ejemplo las ilustra de forma directa.", "Una aserción no sustituye a la validación de entrada del programa. Las pruebas automatizadas formales suelen usar bibliotecas como JUnit."], "Antes de usar una balanza, pruebas con una pesa patrón cuyo valor ya conoces y compruebas que la lectura coincide.", ["public class PruebaArea {", "    static int area(int ancho, int alto) {", "        return ancho * alto;", "    }", "    public static void main(String[] args) {", "        int real = area(4, 3);", "        assert real == 12 : \"4 por 3 debe ser 12\";", "        System.out.println(\"Prueba superada\");", "    }", "}"], ["Declara la clase de prueba.", "Define una función pequeña cuyo resultado se puede comprobar.", "Devuelve el área calculada.", "Cierra el método area.", "Punto de entrada.", "Ejecuta el caso de prueba con valores concretos.", "Comprueba el resultado esperado y adjunta un mensaje útil si falla; habilita assertions con -ea.", "Solo se muestra si la aserción no falla.", "Cierra main.", "Cierra la clase."], [{ step: "Entrada de prueba", values: "ancho=4, alto=3", reason: "Se elige un caso cuyo resultado se conoce." }, { step: "Resultado real", values: "area(4,3)=12", reason: "Se calcula con el mismo código que usa la aplicación." }, { step: "Comparación", values: "12==12 → true", reason: "La aserción confirma el comportamiento esperado." }], ["Prueba superada"], ["Probar solo un caso promedio: añade límites y datos inválidos relevantes.", "Pensar que assert siempre se ejecuta: Java requiere habilitar assertions con -ea.", "Usar assert para validar datos escritos por el usuario: emplea comprobaciones normales."], "Escribe pruebas pequeñas para métodos puros y repítelas cada vez que cambies su implementación."),
  "Depuración de programas": entry("Seguirás la ejecución paso a paso, inspeccionarás variables y aislarás la causa de un resultado incorrecto.", ["Depurar es observar el estado real del programa para localizar la diferencia entre lo esperado y lo ocurrido. Un breakpoint detiene la ejecución en una línea.", "Al avanzar paso a paso, distingue entrar en un método, ejecutar una línea y salir de él. Observa los valores antes y después de asignaciones y condiciones.", "Formula una hipótesis y prueba una causa cada vez. Una tabla de seguimiento manual suele ser suficiente para errores sencillos."], "Si una cuenta no cuadra, revisas cada operación y el valor que tiene cada ingrediente en ese momento, en vez de rehacer la receta al azar.", ["public class Depurar {", "    public static void main(String[] args) {", "        int suma = 0;", "        for (int numero = 1; numero < 4; numero++) {", "            suma += numero;", "        }", "        System.out.println(suma);", "    }", "}"], ["Declara el programa que se va a inspeccionar.", "Punto de entrada donde se coloca un breakpoint inicial.", "Estado inicial de la variable observada.", "Breakpoint útil en la cabecera: verifica inicialización, condición y actualización.", "Línea de cambio de estado: inspecciona suma y numero antes y después.", "Fin del cuerpo y comienzo de la actualización del for.", "Salida que permite comparar el resultado obtenido con el esperado.", "Cierra main.", "Cierra la clase."], [{ step: "Antes de iterar", values: "suma=0, numero=1", reason: "Estado inicial antes del cuerpo." }, { step: "Vuelta 1", values: "suma=1, numero=2", reason: "Se ejecuta suma += numero." }, { step: "Vuelta 2", values: "suma=3, numero=3", reason: "Se acumula el siguiente valor." }, { step: "Vuelta 3", values: "suma=6, numero=4; condición false", reason: "El bucle termina y se imprime seis." }], ["6"], ["Cambiar varias líneas a la vez: aísla una hipótesis para saber qué cambio afectó el resultado.", "Inspeccionar solo la salida final: observa variables intermedias y condiciones.", "Confundir el error observado con su causa: reproduce el caso y sigue el flujo desde el primer estado incorrecto."], "Usa un depurador del IDE para flujos largos; para un cálculo corto, dibuja una tabla de variables a mano.")
}
